package com.ejemplo.alquileres.service;
import com.ejemplo.alquileres.model.*; import java.math.BigDecimal; import java.util.*; import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.springframework.stereotype.Service;
@Service public class ReporteCobranzaExcelService {public byte[] generar(ReporteCobranzaService.Resumen cobros,DashboardService.Resumen dashboard){XSSFWorkbook libro=new XSSFWorkbook();try{CellStyle moneda=libro.createCellStyle();moneda.setDataFormat(libro.createDataFormat().getFormat("\"S/\" #,##0.00"));resumen(libro,cobros,dashboard,moneda);cobros(libro,cobros.cobros(),moneda);cartera(libro,dashboard,moneda);vencimientos(libro,dashboard);return LibroExcel.bytes(libro);}finally{try{libro.close();}catch(java.io.IOException e){throw new IllegalStateException("No se pudo cerrar el Excel.",e);}}}
 private void resumen(XSSFWorkbook l,ReporteCobranzaService.Resumen c,DashboardService.Resumen d,CellStyle m){Sheet s=l.createSheet("Resumen");fila(s,0,"Indicador","Valor");dato(s,1,"Periodo",c.desde()+" al "+c.hasta());numero(s,2,"Total cobrado",c.total(),m);numero(s,3,"Cartera vencida",d.cartera().total(),m);dato(s,4,"Ocupación",d.ocupacion().alquilados()+" de "+d.ocupacion().total());}
 private void cobros(XSSFWorkbook l,List<Pago> ps,CellStyle m){Sheet s=l.createSheet("Cobros");fila(s,0,"Recibo","Fecha","Arrendatario","Inmueble","Capital","Mora","Total","Estado");int r=1;for(Pago p:ps){Row x=s.createRow(r++);x.createCell(0).setCellValue(p.getRecibo());x.createCell(1).setCellValue(String.valueOf(p.getFechaPago()));x.createCell(2).setCellValue(p.getArrendatarioNombre());x.createCell(3).setCellValue(p.getInmuebleNombre());for(int i=4;i<7;i++)x.createCell(i).setCellStyle(m);x.getCell(4).setCellValue(p.getMontoCapital().doubleValue());x.getCell(5).setCellValue(p.getMontoMora().doubleValue());x.getCell(6).setCellValue(p.getMontoTotal().doubleValue());x.createCell(7).setCellValue(p.getEstado().getEtiqueta());}ancho(s,8);}
 private void cartera(XSSFWorkbook l,DashboardService.Resumen d,CellStyle m){Sheet s=l.createSheet("Cartera vencida");fila(s,0,"Arrendatario","Inmueble","Deuda","Días","Semáforo");int r=1;for(DashboardService.Mora q:d.morosos()){Row x=s.createRow(r++);x.createCell(0).setCellValue(q.arrendatario());x.createCell(1).setCellValue(q.inmueble());x.createCell(2).setCellValue(q.deuda().doubleValue());x.getCell(2).setCellStyle(m);x.createCell(3).setCellValue(q.dias());x.createCell(4).setCellValue(q.semaforo().getEtiqueta());}ancho(s,5);}
 private void vencimientos(XSSFWorkbook l,DashboardService.Resumen d){Sheet s=l.createSheet("Contratos por vencer");fila(s,0,"Código","Inmueble","Arrendatario","Fecha fin","Días");int r=1;for(DashboardService.Vencimiento v:d.vencimientos()){Row x=s.createRow(r++);x.createCell(0).setCellValue(v.codigo());x.createCell(1).setCellValue(v.inmueble());x.createCell(2).setCellValue(v.arrendatario());x.createCell(3).setCellValue(String.valueOf(v.fin()));x.createCell(4).setCellValue(v.dias());}ancho(s,5);}private void fila(Sheet s,int r,String...v){Row x=s.createRow(r);for(int i=0;i<v.length;i++)x.createCell(i).setCellValue(v[i]);}private void dato(Sheet s,int r,String a,String b){fila(s,r,a,b);}private void numero(Sheet s,int r,String a,BigDecimal b,CellStyle e){Row x=s.createRow(r);x.createCell(0).setCellValue(a);x.createCell(1).setCellValue(b.doubleValue());x.getCell(1).setCellStyle(e);}private void ancho(Sheet s,int n){for(int i=0;i<n;i++)s.autoSizeColumn(i);}}